include('../config.php');$pagegen=new page_gen();$pagegen->round_to=4;$pagegen->start();$s=new Game();if(!$s->loggedIn||!isset($_GET['time'])){header('Location: ../index.php');exit;}$db=$s->db_link;$uid=(int)$_SESSION['userid'];$gq=$db->query("SELECT allyid FROM users WHERE uid=$uid LIMIT 1");$guildId=(int)(($gq&&$gq->num_rows)?$gq->fetch_assoc()['allyid']:0);if(empty($_SESSION['notify_csrf']))$_SESSION['notify_csrf']=bin2hex(random_bytes(16));$csrf=$_SESSION['notify_csrf'];$notice='';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($csrf,(string)($_POST['csrf']??'')))$error='Security validation failed.';else{$action=(string)($_POST['notification_action']??'');if($action==='read'){$id=(int)($_POST['notification_id']??0);$db->query("UPDATE guild_notifications n INNER JOIN guild_members m ON m.guild_id=n.guild_id AND m.uid=$uid SET n.status='read' WHERE n.notification_id=$id LIMIT 1");$notice='Notification marked read.';}elseif($action==='webhook'&&$guildId>0){$url=trim((string)($_POST['endpoint_url']??''));if(!filter_var($url,FILTER_VALIDATE_URL)||!in_array(parse_url($url,PHP_URL_SCHEME),['https'],true))$error='Webhook endpoint must be an HTTPS URL.';else{$st=$db->prepare('INSERT INTO guild_webhooks(guild_id,endpoint_url) VALUES(?,?)');$st->bind_param('is',$guildId,$url);if($st->execute())$notice='Guild webhook registered.';else$error='Webhook registration failed.';}}}}
$notifications=$guildId?$db->query("SELECT notification_id,title,body,status,created_at FROM guild_notifications WHERE guild_id=$guildId ORDER BY notification_id DESC LIMIT 50"):false;$hooks=$guildId?$db->query("SELECT webhook_id,endpoint_url,enabled,failure_count,last_success_at FROM guild_webhooks WHERE guild_id=$guildId ORDER BY webhook_id DESC LIMIT 10"):false;echo '<div class="comm-shell"><div class="page-hub-head"><span class="rts-kicker">UNIVERSE CIVILIZATION // ALERT NETWORK</span><h3>Guild Notifications</h3><p>Real-time event alerts for pirate invasions, celestial anomalies, raids, and territory operations.</p></div>';if($notice)echo '<div class="comm-alert">'.htmlspecialchars($notice,ENT_QUOTES,'UTF-8').'</div>';if($error)echo '<div class="comm-alert comm-error">'.htmlspecialchars($error,ENT_QUOTES,'UTF-8').'</div>';echo '<section class="comm-card"><h4>Live Event Feed</h4><p>Refresh this console or poll the notification endpoint to receive new alerts.</p><div class="admin-table-wrap"><table><tr><th>Status</th><th>Title</th><th>Message</th><th>Created</th><th>Action</th></tr>';if($notifications)while($n=$notifications->fetch_assoc())echo '<tr><td>'.htmlspecialchars($n['status'],ENT_QUOTES,'UTF-8').'</td><td>'.htmlspecialchars($n['title'],ENT_QUOTES,'UTF-8').'</td><td>'.htmlspecialchars($n['body'],ENT_QUOTES,'UTF-8').'</td><td>'.htmlspecialchars($n['created_at'],ENT_QUOTES,'UTF-8').'</td><td>'.($n['status']==='unread'?'<form method="post" action="modules/notifications.php?time='.time().'" class="inline-form"><input type="hidden" name="csrf" value="'.htmlspecialchars($csrf,ENT_QUOTES,'UTF-8').'"/><input type="hidden" name="notification_action" value="read"/><input type="hidden" name="notification_id" value="'.(int)$n['notification_id'].'"/><button class="comm-btn">Mark Read</button></form>':'Read').'</td></tr>';echo '</table></div></section><section class="comm-card"><h4>Guild Webhook</h4><p>Register an HTTPS endpoint for server-delivered JSON event alerts. Secrets are never displayed in the console.</p><form method="post" action="modules/notifications.php?time='.time().'" class="inline-form"><input type="hidden" name="csrf" value="'.htmlspecialchars($csrf,ENT_QUOTES,'UTF-8').'"/><input type="hidden" name="notification_action" value="webhook"/><input type="url" name="endpoint_url" placeholder="https://example.invalid/guild-events" required><button class="comm-btn">Register Webhook</button></form><div class="admin-table-wrap"><table><tr><th>Endpoint</th><th>Enabled</th><th>Failures</th><th>Last Success</th></tr>';if($hooks)while($h=$hooks->fetch_assoc())echo '<tr><td>'.htmlspecialchars($h['endpoint_url'],ENT_QUOTES,'UTF-8').'</td><td>'.((int)$h['enabled']?'Yes':'No').'</td><td>'.(int)$h['failure_count'].'</td><td>'.htmlspecialchars((string)$h['last_success_at'],ENT_QUOTES,'UTF-8').'</td></tr>';echo '</table></div></section></div>'; $pagegen->stop();print('page generation time: '.$pagegen->gen()); ?>
